import XCTest
import Foundation
@testable import AtlasPCAFhe

/// BFV risk gate on Microsoft SEAL (C target over libsealc): replay of the node-seal corpus plus a native round trip. The corpus is generated by the
/// FHE workflow from the reference (PCA_FHE_SEAL_CORPUS, a .json.gz) and never committed; absent, the replay skips (fails under PCA_FHE_SEAL_REQUIRED=1).
final class FheSealTests: XCTestCase {
    static var required: Bool { ProcessInfo.processInfo.environment["PCA_FHE_SEAL_REQUIRED"] == "1" }

    func policy(_ kappa: Double, _ budget: Double) -> FheRiskPolicy {
        let w = [0.25, 0.2, 0.2, 0.2, 0.1, 0.05]
        return FheRiskPolicy(scale: 1000, dim: 6, weightsScaled: w.map { Int64(($0 * 1000).rounded()) }, kappaWeightsScaled: w.map { Int64((kappa * $0 * 1000).rounded()) },
                             budgetScaled: Int64((budget * 1e6).rounded()), kappa: kappa)
    }

    func ints(_ a: Any?) -> [Int64] { (a as! [NSNumber]).map { $0.int64Value } }

    func testReplaysTheReferenceCiphertextsToTheReferenceResults() throws {
        guard let path = ProcessInfo.processInfo.environment["PCA_FHE_SEAL_CORPUS"], !path.isEmpty else {
            if Self.required { XCTFail("PCA_FHE_SEAL_CORPUS must point at the node-seal corpus") }
            throw XCTSkip("no corpus")
        }
        let p = Process()
        p.executableURL = URL(fileURLWithPath: "/usr/bin/env")
        p.arguments = ["gzip", "-dc", path]
        let pipe = Pipe()
        p.standardOutput = pipe
        try p.run()
        let data = pipe.fileHandleForReading.readDataToEndOfFile()
        p.waitUntilExit()
        XCTAssertEqual(p.terminationStatus, 0)
        let root = try JSONSerialization.jsonObject(with: data) as! [String: Any]
        let seal = root["seal"] as! [String: Any]
        XCTAssertEqual((seal["polyModulusDegree"] as! NSNumber).uint64Value, FheSeal.polyModulusDegree)
        XCTAssertEqual((seal["plainModulus"] as! NSNumber).uint64Value, FheSeal.plainModulus)
        let cases = root["cases"] as! [[String: Any]]
        XCTAssertGreaterThanOrEqual(cases.count, 6)
        for c in cases {
            let pm = c["policy"] as! [String: Any]
            let pol = FheRiskPolicy(scale: (pm["scale"] as! NSNumber).int64Value, dim: (pm["dim"] as! NSNumber).int64Value, weightsScaled: ints(pm["weightsScaled"]),
                                    kappaWeightsScaled: ints(pm["kappaWeightsScaled"]), budgetScaled: (pm["budgetScaled"] as! NSNumber).int64Value, kappa: (pm["kappa"] as! NSNumber).doubleValue)
            let gate = try FheSeal.evalRiskGate(publicKey: root["publicKey"] as! String, galoisKeys: root["galoisKeys"] as! String, encInputs: c["encInputs"] as! String, policy: pol)
            let name = c["name"] as! String
            // deterministic evaluation: byte-equal once both are re-saved uncompressed
            XCTAssertEqual(try FheSeal.canonicalCipher(c["encRiskRaw"] as! String), try FheSeal.canonicalCipher(gate.encRiskRaw), name)
            XCTAssertEqual(try FheSeal.canonicalCipher(c["encSlack"] as! String), try FheSeal.canonicalCipher(gate.encSlack), name)
        }
    }

    func testNativeRoundTripMatchesPlaintextArithmetic() throws {
        let keys = try FheSeal.keygen()
        let cases: [([Int64], Double, Double)] = [([100, 900, 100, 100, 100, 100], 1, 0.6), ([1000, 1000, 1000, 1000, 1000, 1000], 1, 0.5), ([0, 0, 0, 0, 0, 0], 1.5, 0.25)]
        for (x, kappa, budget) in cases {
            let pol = policy(kappa, budget)
            let gate = try FheSeal.evalRiskGate(publicKey: keys.publicKey, galoisKeys: keys.galoisKeys, encInputs: try FheSeal.encryptRiskInputs(publicKey: keys.publicKey, inputsScaled: x), policy: pol)
            let v = try FheSeal.decryptVerdict(secretKey: keys.secretKey, encRiskRaw: gate.encRiskRaw, encSlack: gate.encSlack, policy: pol)
            let raw = zip(pol.weightsScaled, x).reduce(Int64(0)) { $0 + $1.0 * $1.1 }
            let kr = zip(pol.kappaWeightsScaled, x).reduce(Int64(0)) { $0 + $1.0 * $1.1 }
            XCTAssertEqual(v, FheVerdict(rScaled: raw, slack: pol.budgetScaled - kr, admit: pol.budgetScaled - kr >= 0))
        }
    }

    func testAllZeroWeightsEvaluateToZero() throws {
        let keys = try FheSeal.keygen()
        let pol = FheRiskPolicy(scale: 1000, dim: 6, weightsScaled: Array(repeating: 0, count: 6), kappaWeightsScaled: Array(repeating: 0, count: 6), budgetScaled: 5000)
        let gate = try FheSeal.evalRiskGate(publicKey: keys.publicKey, galoisKeys: keys.galoisKeys, encInputs: try FheSeal.encryptRiskInputs(publicKey: keys.publicKey, inputsScaled: [5, 5, 5, 5, 5, 5]), policy: pol)
        XCTAssertEqual(try FheSeal.decryptVerdict(secretKey: keys.secretKey, encRiskRaw: gate.encRiskRaw, encSlack: gate.encSlack, policy: pol), FheVerdict(rScaled: 0, slack: 5000, admit: true))
    }

    func testWrongKeyFailsClosed() throws {
        let a = try FheSeal.keygen(), b = try FheSeal.keygen()
        let pol = policy(1, 0.6)
        let gate = try FheSeal.evalRiskGate(publicKey: a.publicKey, galoisKeys: a.galoisKeys, encInputs: try FheSeal.encryptRiskInputs(publicKey: a.publicKey, inputsScaled: [1, 2, 3, 4, 5, 6]), policy: pol)
        XCTAssertThrowsError(try FheSeal.decryptVerdict(secretKey: b.secretKey, encRiskRaw: gate.encRiskRaw, encSlack: gate.encSlack, policy: pol)) {
            guard case FheError.invalid(let m) = $0 else { return XCTFail("\($0)") }
            XCTAssertTrue(m.contains("noise budget"))
        }
    }

    func testMalformedBlobsAndPoliciesAreRefused() throws {
        let keys = try FheSeal.keygen()
        let good = try FheSeal.encryptRiskInputs(publicKey: keys.publicKey, inputsScaled: [1, 2, 3, 4, 5, 6])
        for bad in [String(good.dropLast(8)), good + "AAAA", "AAAA", String(repeating: "A", count: 64)] {
            XCTAssertThrowsError(try FheSeal.assertSealBlob(bad, "x"))
        }
        let z = [Int64](repeating: 0, count: 6)
        let bads = [FheRiskPolicy(scale: 1000, dim: 5, weightsScaled: z, kappaWeightsScaled: z, budgetScaled: 0), FheRiskPolicy(scale: 1000, dim: 6, weightsScaled: z, kappaWeightsScaled: z, budgetScaled: FheSeal.signedBound),
                    FheRiskPolicy(scale: 0, dim: 6, weightsScaled: z, kappaWeightsScaled: z, budgetScaled: 0), FheRiskPolicy(scale: 1000, dim: 6, weightsScaled: [0, 0, 0, 0, 0], kappaWeightsScaled: z, budgetScaled: 0)]
        for bad in bads { XCTAssertThrowsError(try FheSeal.requirePolicy(bad)) }
    }
}
